func TestLv3_Partition(t *testing.T) {
	var kvs []KeyValue
	for _, f := range inputNames {
		for _, w := range refWords(inputs[f]) {
			kvs = append(kvs, KeyValue{w, "1"})
		}
	}
	for _, n := range []int{1, 2, 3, 4} {
		got := Partition(append([]KeyValue(nil), kvs...), n)
		if len(got) != n {
			fail(t, "part_len", say("Partition(kvs, %d) 应该返回 %d 个桶，实际返回了 %d 个。", "Partition(kvs, %d) should return %d buckets, returned %d.", n, n, len(got)))
		}
		for y, b := range got {
			for _, kv := range b {
				if ihash(kv.Key)%n != y {
					fail(t, "part_bucket", say("nReduce=%d 时，%q 应该在第 %d 号桶，却出现在第 %d 号桶。", "With nReduce=%d, %q belongs in bucket %d but appeared in bucket %d.", n, kv.Key, ihash(kv.Key)%n, y))
				}
			}
			var want []KeyValue
			for _, kv := range kvs {
				if ihash(kv.Key)%n == y {
					want = append(want, kv)
				}
			}
			if len(want) != len(b) || (len(b) > 0 && !reflect.DeepEqual(want, b)) {
				fail(t, "part_order", say("第 %d 号桶应有 %d 个键值对，并保持原来的顺序；实际有 %d 个。", "Bucket %d should hold %d pairs in their original order; it has %d.", y, len(want), len(b)))
			}
		}
	}
}

func TestLv3_ReduceLines(t *testing.T) {
	var kvs []KeyValue
	for _, w := range refWords(inputs["pg-1.txt"] + " " + inputs["pg-2.txt"]) {
		kvs = append(kvs, KeyValue{w, "1"})
	}
	rand.New(rand.NewSource(3)).Shuffle(len(kvs), func(i, j int) { kvs[i], kvs[j] = kvs[j], kvs[i] })
	got := ReduceLines(kvs, Reduce)
	want := refLines(refCounts(inputs["pg-1.txt"] + " " + inputs["pg-2.txt"]))
	keys := map[string]bool{}
	for _, l := range got {
		k := strings.SplitN(l, " ", 2)[0]
		if keys[k] {
			fail(t, "not_grouped", say("同一个键只能输出一行，但 %q 出现了多次。要先把相同的键分到一组。", "Each key gets exactly one line, but %q appears more than once. Group equal keys together first.", k))
		}
		keys[k] = true
	}
	if !sort.StringsAreSorted(got) {
		fail(t, "unsorted", say("输出要按键排序（sort.Strings 的默认顺序）。", "The output must be sorted by key (the default order of sort.Strings)."))
	}
	if !reflect.DeepEqual(got, want) {
		var first twoLang
		for i := range want {
			if i >= len(got) || got[i] != want[i] {
				if i < len(got) {
					first = say("第 %d 行应为 %q，实际是 %q。", "Line %d should be %q, got %q.", i+1, want[i], got[i])
				} else {
					first = say("第 %d 行应为 %q，实际没有这一行。", "Line %d should be %q, but it is missing.", i+1, want[i])
				}
				break
			}
		}
		fail(t, "lines_content", twoLang{"格式应该是 \"键 结果\"。" + first.zh, "The format is \"key result\". " + first.en})
	}
}
